class TimelineSummary(BaseModel):
    """
    Values derived from a [`ChangeTimeline`]. EVERY field is an
    [`Observation`]: `measured` with the value, `absent` when the producer
    looked over the whole window and the thing did not occur, or `unknown`
    with a closed `UnknownCode` when it could not look. No field is a verdict
    and no threshold is applied.

    Each field's `provenance.source` carries `window` and `observedSources`;
    a field derived from an event type the recorder capped carries
    `provenance.coverage.unmeasured[{ dimension: "timeline-events:<type>", … }]`.
    """

    animationsUnsettledAtEnd: Annotated[
        Observation31,
        Field(
            description='Animations/transitions running when recording ended. Degraded\n(`coverage.unmeasured`) where `document.getAnimations` is missing.'
        ),
    ]
    expectedStates: Annotated[
        list[ExpectedStateResult],
        Field(
            description='One entry per requested `expectStates` id, in request order; `[]` when\nnone were requested.'
        ),
    ]
    firstResponseMs: Annotated[
        Observation,
        Field(
            description='Offset of the first RESPONSE event (elements-*, page-changed,\nlayout-shift, animation-*, state-*). `unknown{no_event_before_timeout}`\nwhen nothing responded in the window.'
        ),
    ]
    layoutShiftAfterFirstResponseMs: Annotated[
        Observation,
        Field(
            description='Offset of the LAST layout shift minus `firstResponseMs`. `absent` when\nno shift occurred.'
        ),
    ]
    layoutShiftCount: Annotated[
        Observation21,
        Field(description='Number of `layout-shift` events. Same unknown rule.'),
    ]
    layoutShiftTotal: Annotated[
        Observation,
        Field(
            description='Sum of `layout-shift` values in the window.\n`unknown{performance_observer_unsupported}` where the entry type is\nmissing.'
        ),
    ]
    longTaskTotalMs: Annotated[
        Observation,
        Field(
            description='Sum of `long-task` durations (ms).\n`unknown{performance_observer_unsupported}` where `longtask` is\nmissing.'
        ),
    ]
    settleMs: Annotated[
        Observation,
        Field(
            description='Offset of the `settled` event. `unknown{no_event_before_timeout}` when\nthe UI did not settle within `settleTimeout`.'
        ),
    ]


class ChangeTimeline(BaseModel):
    """
    The interaction timeline: action → every observed event → settled, each
    with its offset from the action, plus a derived [`TimelineSummary`].
    """

    events: Annotated[
        list[TimelineEvent],
        Field(
            description='Timestamped events, ordered by `offsetMs` (ties keep arrival order).'
        ),
    ]
    observedSources: Annotated[
        list[TimelineSource],
        Field(description='The sources this recording could observe.'),
    ]
    recordedMs: Annotated[
        float,
        Field(
            description='How long the timeline was recorded, from action start (ms): the settle\nwindow, extended by any `withinMs` window. Not the settle time.'
        ),
    ]
    settled: Annotated[
        bool,
        Field(
            description='Whether the UI reached a stable state within `settleTimeout`.'
        ),
    ]
    summary: Annotated[
        TimelineSummary, Field(description='Values derived from `events`.')
    ]
